import type { Dict } from "./en";

/// Punjabi (Gurmukhi).
///
/// Two rules held throughout, because a dictionary written by translating
/// word-for-word reads like a machine did it:
///
/// 1. Where Punjabi has its own cricket word, it wins. A four is ਚੌਕਾ and a
///    six is ਛੱਕਾ — every Punjabi commentator says these, and "ਫ਼ੋਰ" would
///    read as a foreigner's guess.
/// 2. Where it does not, the transliteration commentators actually use wins.
///    Fielding positions are said in English on Punjabi broadcasts, so
///    "ਮਿਡ-ਵਿਕਟ" is right and inventing a Punjabi compound for mid-wicket
///    would leave a scorer unable to recognise their own field.
