  // ਸ਼ਰਮਾ ਦੀ ਗੇਂਦ, ਸਿੰਘ ਨੇ ਕਵਰ ਵੱਲ ਡਰਾਈਵ ਕੀਤਾ — ਚੌਕਾ
  // "Sharma's ball, Singh drove towards cover — four". The stroke lands
  // before the outcome and the region before the verb, which is the order
  // Punjabi commentary actually uses; the English order word-for-word would
  // be grammatical nonsense.
  "ball.bowler_to_batter": "{bowler} ਦੀ ਗੇਂਦ, {batter}",
  "ball.batter_only": "{batter}",
  "ball.with_shot": "{who} {shot} — {outcome}",
  "ball.without_shot": "{who} — {outcome}",
  // The agentive ਨੇ lives on the stroke, not on the batter's name, and that
  // placement is load-bearing. ਨੇ marks the doer of a completed action and so
  // demands a verb after it: "ਸਿੰਘ ਨੇ ਕਵਰ ਵੱਲ ਡਰਾਈਵ ਕੀਤਾ" is right, but a ball
  // with no stroke recorded gave "ਸਿੰਘ ਨੇ 1 ਰਨ" — an agent, an object and no
  // verb at all, which is not a sentence. Keeping ਨੇ here means it appears
  // only when there is a stroke for it to govern, and a ball without one
  // reads as a scoreline instead.
  "shot.phrase.through": "ਨੇ {region} ਵੱਲ {verb}",
  "shot.phrase.down_ground": "ਨੇ ਸਿੱਧਾ {region} ਵੱਲ {verb}",
  "shot.phrase.down_to": "ਨੇ {region} ਵੱਲ {verb}",
  "shot.phrase.plain": "ਨੇ {verb}",

