  "sc.a_patel": "ਏ ਪਟੇਲ",
  "sc.someone_else_is_scoring_this_match_onl": "ਕੋਈ ਹੋਰ ਇਹ ਮੈਚ ਸਕੋਰ ਕਰ ਰਿਹਾ ਹੈ। ਜਦੋਂ ਤੱਕ ਉਹ ਬੁੱਕ ਨਹੀਂ ਸੌਂਪਦੇ, ਸਿਰਫ਼ ਉਹੀ ਗੇਂਦ ਦਰਜ ਕਰ ਸਕਦੇ ਹਨ।",
  "sc.name_them_and_the_book_starts_in_their": "ਨਾਮ ਦੇਣ 'ਤੇ ਬੁੱਕ ਉਨ੍ਹਾਂ ਦੇ ਹੱਥ ਵਿੱਚ ਸ਼ੁਰੂ ਹੁੰਦੀ ਹੈ। ਉਹ ਇਸਨੂੰ ਕਿਸੇ ਵੀ ਖੇਡ ਰਹੇ ਖਿਡਾਰੀ ਨੂੰ, ਕਿਸੇ ਵੀ ਟੀਮ ਦੇ, ਸੌਂਪ ਸਕਦੇ ਹਨ। ਖਾਲੀ ਛੱਡੋ ਤਾਂ ਜੋ ਬੁੱਕ ਲਵੇਗਾ ਉਸੇ ਕੋਲ ਰਹੇਗੀ।",
  "sc.they_take_over_recording_every_ball_fr": "ਉਹ ਅਗਲੀ ਗੇਂਦ ਤੋਂ ਹਰ ਗੇਂਦ ਦਰਜ ਕਰਨਾ ਸੰਭਾਲ ਲੈਣਗੇ। ਤੁਸੀਂ ਦੇਖਦੇ ਰਹੋਗੇ, ਅਤੇ ਬੁੱਕ ਵਾਪਸ ਲੈ ਸਕਦੇ ਹੋ। ਕਿਸੇ ਵੀ ਟੀਮ ਦਾ ਕੋਈ ਵੀ ਖੇਡ ਰਿਹਾ ਖਿਡਾਰੀ ਇਹ ਲੈ ਸਕਦਾ ਹੈ।",
  "sc.it_goes_down_as_no_result_the_scorecar": "ਇਹ ਬਿਨਾਂ ਨਤੀਜੇ ਦੇ ਦਰਜ ਹੋਵੇਗਾ। ਸਕੋਰਕਾਰਡ ਅਤੇ ਹੁਣ ਤੱਕ ਦਾ ਸਾਰਾ ਸਕੋਰ ਰਹੇਗਾ — ਇਹ ਹੋਇਆ ਸੀ, ਅਤੇ ਔਸਤਾਂ ਵਿੱਚ ਗਿਣਿਆ ਜਾਵੇਗਾ। ਇਹ ਵਾਪਸ ਨਹੀਂ ਲਿਆ ਜਾ ਸਕਦਾ।",
  "sc.nothing_has_been_scored_so_the_match_i": "ਕੁਝ ਵੀ ਸਕੋਰ ਨਹੀਂ ਹੋਇਆ, ਇਸ ਲਈ ਮੈਚ ਪੂਰੀ ਤਰ੍ਹਾਂ ਹਟਾ ਦਿੱਤਾ ਜਾਵੇਗਾ ਅਤੇ ਫ਼ਿਕਸਚਰ ਰਹੇਗਾ। ਜੇ ਇੱਕ ਵੀ ਗੇਂਦ ਸੁੱਟੀ ਗਈ ਹੋਵੇ ਤਾਂ ਇਸਦੀ ਥਾਂ ਮੈਚ ਰੱਦ ਕਰੋ, ਅਤੇ ਸਕੋਰਕਾਰਡ ਰੱਖੋ।",
  "sc.worked_out_from_the_card_runs_and_wick": "ਸਕੋਰਕਾਰਡ ਤੋਂ ਕੱਢਿਆ ਗਿਆ — ਰਨ ਅਤੇ ਵਿਕਟਾਂ ਨੂੰ ਮੈਚ ਦੇ ਹਾਲਾਤ ਨਾਲ ਤੋਲ ਕੇ। ਤੁਸੀਂ ਬਦਲ ਸਕਦੇ ਹੋ।",
  "sc.set_how_the_game_is_being_played_then": "ਤੈਅ ਕਰੋ ਕਿ ਮੈਚ ਕਿਵੇਂ ਖੇਡਿਆ ਜਾ ਰਿਹਾ ਹੈ, ਫਿਰ ਦੱਸੋ ਕਿ ਪੇਸ਼ਕਸ਼ ਕੌਣ ਕਰ ਰਿਹਾ ਹੈ। ਦੂਜੇ ਕਪਤਾਨ ਤੋਂ ਸਹਿਮਤੀ ਮੰਗੀ ਜਾਵੇਗੀ।",
  "sc.law_41_a_second_beamer_or_short_pitche": "ਕਾਨੂੰਨ 41: ਦੂਜਾ ਬੀਮਰ, ਜਾਂ ਆਖ਼ਰੀ ਚੇਤਾਵਨੀ ਤੋਂ ਬਾਅਦ ਸ਼ਾਰਟ-ਪਿੱਚ ਗੇਂਦਬਾਜ਼ੀ। ਉਹ ਮੈਦਾਨ ਵਿੱਚ ਰਹਿੰਦੇ ਹਨ ਅਤੇ ਫ਼ੀਲਡਿੰਗ ਕਰਦੇ ਰਹਿੰਦੇ ਹਨ — ਬੱਸ ਇਸ ਪਾਰੀ ਵਿੱਚ ਦੁਬਾਰਾ ਗੇਂਦਬਾਜ਼ੀ ਨਹੀਂ ਕਰਨਗੇ, ਅਤੇ ਵਾਪਸੀ ਦਾ ਕੋਈ ਰਾਹ ਨਹੀਂ।",
  "sc.two_innings_a_side_won_on_aggregate_a": "ਹਰ ਟੀਮ ਦੀਆਂ ਦੋ ਪਾਰੀਆਂ, ਕੁੱਲ ਜੋੜ 'ਤੇ ਜਿੱਤ। ਕਪਤਾਨ ਪਾਰੀ ਜਲਦੀ ਬੰਦ ਕਰ ਸਕਦਾ ਹੈ, ਪੂਰੀ ਛੱਡ ਸਕਦਾ ਹੈ, ਜਾਂ ਟੀਮਾਂ ਕੋਲ ਸਮਾਂ ਮੁੱਕ ਸਕਦਾ ਹੈ — ਅਤੇ ਇੱਥੇ ਡਰਾਅ ਵੀ ਇੱਕ ਨਤੀਜਾ ਹੈ, ਨਤੀਜੇ ਦੀ ਅਣਹੋਂਦ ਨਹੀਂ।",
  "sc.the_umpire_has_signalled_one_short_the": "ਅੰਪਾਇਰ ਨੇ ਵਨ ਸ਼ਾਰਟ ਦਾ ਇਸ਼ਾਰਾ ਕੀਤਾ ਹੈ: ਅਗਲੀ ਗੇਂਦ 'ਤੇ ਇੱਕ ਰਨ ਘੱਟ ਮਿਲੇਗਾ, ਪਰ ਬੱਲੇਬਾਜ਼ ਉੱਥੇ ਹੀ ਰਹਿਣਗੇ ਜਿੱਥੇ ਤੱਕ ਦੌੜੇ ਸਨ।",

