  // The tour film
  "tour.opening": "{brand} ਫ਼ੋਨ ਉੱਤੇ ਕਲੱਬ ਕ੍ਰਿਕਟ ਹੈ: ਫ਼ਿਕਸਚਰ, ਉਪਲਬਧਤਾ, ਟੀਮ ਚੋਣ ਅਤੇ ਸਕੋਰਬੁੱਕ। ਇਹ ਇੱਕ ਖਿਡਾਰੀ ਪਹਿਲੀ ਵਾਰ ਇਸਨੂੰ ਖੋਲ੍ਹ ਰਿਹਾ ਹੈ।",

  // Tour beats
  "tour.signing_up_asks_one_thing_first_whethe": "ਸਾਈਨ ਅੱਪ ਪਹਿਲਾਂ ਇੱਕ ਗੱਲ ਪੁੱਛਦਾ ਹੈ — ਤੁਸੀਂ ਕਲੱਬ ਚਲਾਉਂਦੇ ਹੋ ਜਾਂ ਕਿਸੇ ਲਈ ਖੇਡਦੇ ਹੋ। ਦੋਵਾਂ ਲਈ ਐਪ ਦੀ ਸ਼ਕਲ ਵੱਖਰੀ ਹੈ।",
  "tour.the_secretary_sends_the_invite_from_th": "ਸਕੱਤਰ ਉਸੇ ਲਿੰਕ ਤੋਂ ਸੱਦਾ ਭੇਜਦਾ ਹੈ, ਅਤੇ ਉਹ ਮੁੱਖ ਪੰਨੇ 'ਤੇ ਉਡੀਕ ਰਿਹਾ ਹੁੰਦਾ ਹੈ — ਨਾ ਕੋਈ ਕੋਡ ਟਾਈਪ ਕਰਨਾ, ਨਾ ਕੋਈ ਈਮੇਲ ਲੱਭਣੀ।",
  "tour.three_taps_available_maybe_can_t_play": "ਤਿੰਨ ਟੈਪ — ਉਪਲਬਧ, ਸ਼ਾਇਦ, ਨਹੀਂ ਖੇਡ ਸਕਦਾ। ਜਵਾਬ ਟੈਪ ਕਰਦੇ ਸਾਰ ਸੰਭਾਲਿਆ ਜਾਂਦਾ ਹੈ ਅਤੇ ਕਪਤਾਨ ਨੂੰ ਤੁਰੰਤ ਦਿਖ ਜਾਂਦਾ ਹੈ।",
  "tour.nobody_bowls_two_overs_in_a_row_and_no": "ਕੋਈ ਲਗਾਤਾਰ ਦੋ ਓਵਰ ਨਹੀਂ ਕਰਦਾ ਅਤੇ ਕੋਈ ਆਪਣੇ ਚਾਰ ਤੋਂ ਵੱਧ ਨਹੀਂ ਕਰਦਾ, ਇਸ ਲਈ ਓਵਰ ਖ਼ਤਮ ਹੁੰਦੇ ਹੀ ਐਪ ਪੁੱਛਦੀ ਹੈ ਕਿ ਅਗਲਾ ਕੌਣ ਹੈ — ਅਤੇ ਦੱਸਦੀ ਹੈ ਕਿ ਕੌਣ ਨਹੀਂ ਕਰ ਸਕਦਾ।",
  "tour.the_chase_with_the_target_the_rate_it": "ਪਿੱਛਾ, ਟੀਚੇ, ਲੋੜੀਂਦੀ ਦਰ ਅਤੇ ਨਾਲ ਹੀ ਡਕਵਰਥ–ਲੁਈਸ–ਸਟਰਨ ਪਾਰ ਸਕੋਰ ਸਮੇਤ, ਜੇ ਮੀਂਹ ਆ ਜਾਵੇ।",
  "tour.the_wagon_wheel_is_built_from_the_same": "ਵੈਗਨ ਵ੍ਹੀਲ ਉਹਨਾਂ ਹੀ ਗੇਂਦਾਂ ਤੋਂ ਬਣਦਾ ਹੈ — ਹਰ ਰਨ ਵਾਲਾ ਸ਼ਾਟ, ਕਿੱਧਰ ਗਿਆ ਅਤੇ ਕਿਹੜਾ ਸਟ੍ਰੋਕ ਸੀ।",
  "tour.scorers_get_it_wrong_three_balls_back": "ਸਕੋਰਰ ਤੋਂ ਗ਼ਲਤੀ ਤਿੰਨ ਗੇਂਦ ਪਿੱਛੇ ਵੀ ਹੁੰਦੀ ਹੈ, ਸਿਰਫ਼ ਆਖ਼ਰੀ 'ਤੇ ਨਹੀਂ। ਗੇਂਦ ਚੁਣੋ ਅਤੇ ਪਾਰੀ ਉੱਥੇ ਤੱਕ ਵਾਪਸ ਚਲੀ ਜਾਂਦੀ ਹੈ — ਦਰਜ ਹੁੰਦਾ ਹੈ, ਮਿਟਾਇਆ ਨਹੀਂ ਜਾਂਦਾ।",
  "tour.the_club_s_season_folded_up_out_of_tho": "ਕਲੱਬ ਦਾ ਸੀਜ਼ਨ, ਉਹਨਾਂ ਹੀ ਕਾਰਡਾਂ ਤੋਂ ਬਣਿਆ: ਰਨ, ਵਿਕਟਾਂ, ਕੈਚ — ਇਹ ਕੋਈ ਟਾਈਪ ਨਹੀਂ ਕਰਦਾ।",
  "tour.the_club_s_public_page_record_top_play": "ਕਲੱਬ ਦਾ ਜਨਤਕ ਪੰਨਾ — ਰਿਕਾਰਡ, ਵਧੀਆ ਖਿਡਾਰੀ ਅਤੇ ਅਗਲੇ ਫ਼ਿਕਸਚਰ — ਹਰ ਉਸ ਲਈ ਜਿਸ ਨੇ ਕਲੱਬ ਬਾਰੇ ਸੁਣਿਆ ਹੈ ਪਰ ਖਾਤਾ ਨਹੀਂ ਹੈ।",

